head.b:skin:
/* The Bliss Central Suites | design: Hotel/Hospitality, hero-centric, navy + gold, Cormorant + Montserrat */
/* Photos live in the style block just before the WhatsApp button, near the end of this file. */
:root{--ridge:none}
:root{--ink:#0F1E36;--ink2:#1B3358;--gold:#A16207;--gold-lt:#E3C072;--bg:#F8FAFC;--card:#fff;--mut:#475569;--line:#D5DCE6;--r:14px}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:76px}
body{margin:0;background:var(--bg);color:var(--ink);font:400 16px/1.6 Montserrat,system-ui,sans-serif}
h1,h2,h3{font-family:Cormorant,Georgia,serif;font-weight:600;line-height:1.1;margin:0}
h2{font-size:clamp(2rem,4.2vw,3rem)}
h3{font-size:1.7rem}
p{margin:0}
a{color:inherit}
:focus-visible{outline:3px solid var(--gold);outline-offset:3px}
.skip{position:absolute;left:-999px;top:8px;background:#fff;padding:10px 16px;z-index:99}
.skip:focus{left:8px}
.w{max-width:1120px;margin:0 auto;padding:0 20px}
section{padding:clamp(56px,9vw,104px) 0}
.lead{color:var(--mut);max-width:60ch;margin-top:14px}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 24px;border-radius:999px;border:0;background:var(--ink);color:#fff;font:600 .95rem Montserrat,sans-serif;text-decoration:none;cursor:pointer;transition:background .2s}
.btn:hover{background:var(--ink2)}
.btn.gold{background:var(--gold-lt);color:var(--ink)}
.btn.gold:hover{background:#efd38e}
/* header */
.top{position:sticky;top:0;z-index:20;background:rgba(15,30,54,.96);color:#fff}
.top .w{display:flex;align-items:center;gap:28px;min-height:68px}
.brand{font:600 1.55rem Cormorant,serif;text-decoration:none;margin-right:auto;line-height:1}
.brand small{display:block;font:400 .72rem Montserrat,sans-serif;color:#C9D3E3;margin-top:4px}
.top nav{display:flex;gap:26px}
.top nav a{text-decoration:none;font-size:.9rem;color:#E2E8F0;padding:12px 0}
.top nav a:hover{color:var(--gold-lt)}
.top .btn{min-height:44px}
/* hero */
.hero{position:relative;overflow:hidden;color:#fff;padding:clamp(72px,14vw,150px) 0 clamp(120px,16vw,190px);background:radial-gradient(120% 70% at 70% 100%,#C98E3A 0,rgba(201,142,58,0) 55%),linear-gradient(#0B1730,#24467F 78%)}
.hero h1{font-size:clamp(2.5rem,6.4vw,5rem);font-weight:500;max-width:15ch;position:relative;z-index:2}
.hero p{max-width:46ch;margin-top:22px;color:#E2E8F0;font-size:1.05rem;position:relative;z-index:2}
.hero svg{position:absolute;left:0;bottom:-1px;width:100%;height:auto;min-height:170px}
.hero .r{animation:rise 1.3s cubic-bezier(.2,.7,.2,1) both}
.hero .r2{animation-delay:.18s}.hero .r3{animation-delay:.36s}
@keyframes rise{from{transform:translateY(70px);opacity:0}to{transform:none;opacity:1}}
/* booking bar */
.book{position:relative;z-index:3;margin-top:-52px;padding:0 0 8px}
.book form{display:grid;grid-template-columns:1.3fr 1fr 1fr .8fr auto;gap:14px;align-items:end;background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:20px;box-shadow:0 18px 40px rgba(15,30,54,.16)}
.book label{display:block;font-size:.8rem;font-weight:600;color:var(--mut);margin-bottom:6px}
.book select,.book input{width:100%;min-height:48px;border:1px solid #94A3B8;border-radius:10px;padding:0 12px;font:400 1rem Montserrat,sans-serif;color:var(--ink);background:#fff}
.err{min-height:1.4em;margin:10px 4px 0;font-size:.88rem;color:#B91C1C}
.note{font-size:.85rem;color:var(--mut);margin:0 4px}
/* suites: one feature, two supporting */
.suites{display:grid;grid-template-columns:1.35fr 1fr;gap:20px;margin-top:40px}
.suite{background:var(--card);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;display:flex;flex-direction:column}
.suite.main{grid-row:span 2}
.ph{aspect-ratio:16/10}
.suite.main .ph{aspect-ratio:4/3}
.suite .t{padding:22px 24px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.suite .t p{color:var(--mut);font-size:.95rem}
.suite .t a{margin-top:auto;font-weight:600;color:var(--gold);text-underline-offset:4px;padding:10px 0}
.tags{display:flex;flex-wrap:wrap;gap:8px}
.tags span{border:1px solid var(--line);border-radius:999px;padding:3px 12px;font-size:.78rem;color:var(--mut)}
/* amenities */
.am{background:#EEF1F6}
.amg{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 40px;margin-top:44px}
.amg svg{width:28px;height:28px;stroke:var(--gold);fill:none;stroke-width:1.75;stroke-linecap:round;stroke-linejoin:round}
.amg h3{font-size:1.35rem;margin:10px 0 4px}
.amg p{color:var(--mut);font-size:.92rem}
/* location */
.loc{display:grid;grid-template-columns:1fr 1.15fr;gap:48px;align-items:start}
.loc dl{margin:30px 0 0}
.loc dl div{display:flex;justify-content:space-between;gap:16px;padding:13px 0;border-bottom:1px solid var(--line)}
.loc dt{font-weight:500}.loc dd{margin:0;color:var(--mut);text-align:right}
.map{border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:#fff}
.map iframe{display:block;width:100%;aspect-ratio:4/3;border:0}
.map a{display:block;padding:12px 16px;font-weight:600;font-size:.9rem;color:var(--gold)}
/* good to know */
.faq{max-width:760px;margin-top:34px}
details{border-top:1px solid var(--line)}
details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;min-height:56px;display:flex;align-items:center;font:600 1.3rem Cormorant,serif;list-style:none}
summary::-webkit-details-marker{display:none}
summary::after{content:'+';margin-left:auto;font:400 1.5rem Montserrat,sans-serif;color:var(--gold)}
details[open] summary::after{content:'\2212'}
details p{padding:0 0 20px;color:var(--mut)}
/* footer */
.foot{background:var(--ink);color:#CBD5E1;padding:56px 0 30px}
.foot .w{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:34px}
.foot h3{color:#fff;font-size:1.6rem;margin-bottom:10px}
.foot a{color:var(--gold-lt)}
.foot .attr{grid-column:1/-1;border-top:1px solid #2C3E5C;padding-top:20px;font-size:.8rem}
/* blog pages */
.post-area{padding:48px 0}
.post{max-width:720px;margin:0 auto 48px}
.post-title{font-size:clamp(2rem,4vw,3rem);margin-bottom:16px}
.post-body img{max-width:100%;height:auto}
body.pt-index .post-area{display:none}
@media(max-width:900px){
.book form{grid-template-columns:1fr 1fr}
.book form .btn{grid-column:1/-1}
.suites,.loc{grid-template-columns:1fr}
.suite.main{grid-row:auto}
.amg{grid-template-columns:1fr 1fr}
.foot .w{grid-template-columns:1fr}
.top nav{display:none}
}
@media(max-width:520px){.book form,.amg{grid-template-columns:1fr}.top .btn{padding:0 16px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.hero .r{animation:none}}

.btn.ghost{background:transparent;color:#fff;border:1.5px solid #E2E8F0}
.btn.ghost:hover{background:rgba(255,255,255,.14)}
.hero::after{content:'';position:absolute;inset:0;z-index:1;background:linear-gradient(rgba(11,23,48,.78),rgba(11,23,48,.6))}
.hero .w{position:relative;z-index:2}
.hero svg{display:var(--ridge);z-index:1}
.cta{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.ph,.gt{background:var(--gi,none) center/cover,linear-gradient(160deg,#2B4B7A,#0F1E36)}
.trust{padding:34px 0 0}
.trust ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.trust li{font-size:.88rem;color:var(--mut)}
.trust b{display:block;color:var(--ink);font:600 1.45rem Cormorant,serif}
.price{font:600 1.5rem Cormorant,serif;color:var(--ink)}
.price small{font:400 .8rem Montserrat,sans-serif;color:var(--mut);margin-left:6px}
.suite ul{margin:0;padding-left:18px;color:var(--mut);font-size:.9rem}
.gal{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:40px}
.gt{position:relative;aspect-ratio:4/3;border-radius:var(--r);overflow:hidden;margin:0}
.gt figcaption{position:absolute;inset:auto 0 0;padding:36px 16px 12px;color:#fff;font-weight:600;font-size:.9rem;background:linear-gradient(transparent,rgba(11,23,48,.82))}
.offers{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:40px}
.offer{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--gold);border-radius:var(--r);padding:24px;display:flex;flex-direction:column;gap:10px}
.offer p{color:var(--mut);font-size:.95rem}
.offer a{margin-top:auto;font-weight:600;color:var(--gold);padding:10px 0;text-underline-offset:4px}
.abt,.rev,.cont{display:grid;grid-template-columns:1.2fr 1fr;gap:48px;align-items:start}
.abt p{color:var(--mut)}.abt p+p{margin-top:14px}.abt h3{margin:26px 0 8px}
.hl{margin:0;padding:0 0 0 22px;list-style:none;border-left:3px solid var(--gold-lt)}
.hl li{padding:9px 0}
.score{font:600 5.5rem/1 Cormorant,serif}
.rev p{color:var(--mut);margin-top:10px}
.rev .btn{margin-top:22px}
.cont dl{margin:26px 0 0}.cont dt{font-weight:600;margin-top:16px}.cont dd{margin:2px 0 0;color:var(--mut)}
.cf input,.cf textarea{width:100%;min-height:48px;border:1px solid #94A3B8;border-radius:10px;padding:10px 12px;font:400 1rem Montserrat,sans-serif;color:var(--ink);background:#fff}
.cf label{display:block;font-size:.8rem;font-weight:600;color:var(--mut);margin:14px 0 6px}
.cf .btn{margin-top:20px}
.wa{position:fixed;right:16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:30;width:56px;height:56px;border-radius:50%;background:#12803F;display:grid;place-items:center;box-shadow:0 8px 24px rgba(0,0,0,.28)}
.wa svg{width:30px;height:30px;stroke:#fff;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.top nav{gap:18px}.top nav a{font-size:.84rem}
.mbtn{display:none;background:none;border:1px solid #5A7098;color:#fff;border-radius:10px;min-height:44px;padding:0 14px;font:600 .88rem Montserrat,sans-serif;cursor:pointer}
@media(max-width:1080px){.mbtn{display:inline-flex;align-items:center}.top nav{display:none;position:absolute;left:0;right:0;top:100%;background:var(--ink);flex-direction:column;gap:0;padding:6px 20px 16px;border-top:1px solid #2C3E5C}.top.open nav{display:flex}.top nav a{padding:14px 0;font-size:1rem}}
@media(max-width:900px){.gal{grid-template-columns:1fr 1fr}.offers,.abt,.rev,.cont{grid-template-columns:1fr}.trust ul{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.gal{grid-template-columns:1fr}.top .w{gap:10px}.brand small{display:none}.brand{font-size:1.3rem}.mbtn{padding:0 10px}}

.hero{min-height:min(88vh,760px)}
.sl{position:absolute;inset:0;z-index:0;opacity:0;background-position:center;background-size:cover;background-repeat:no-repeat;animation:hs 18s ease-in-out infinite;will-change:opacity,transform}
.s1{background-image:var(--i1);background-position:center 35%;animation-delay:-1.4s}
.s2{background-image:var(--i2);animation-delay:4.6s}
.s3{background-image:var(--i3);animation-delay:10.6s}
@keyframes hs{0%{opacity:0;transform:scale(1)}8%{opacity:1}33%{opacity:1}41%{opacity:0;transform:scale(1.1)}100%{opacity:0;transform:scale(1.1)}}
.fade{position:relative;overflow:hidden}
.fade span{position:absolute;inset:0;opacity:0;background-position:center;background-size:cover;animation:xf 10s ease-in-out infinite}
.fade span:first-child{opacity:1}
.fade span+span{animation-delay:5s}
@keyframes xf{0%,45%{opacity:1}55%,95%{opacity:0}100%{opacity:1}}
.gal{grid-auto-flow:dense}
.gt.big{grid-column:span 2;grid-row:span 2;aspect-ratio:auto}
.gt.wide{grid-column:span 2;aspect-ratio:auto}
@media(max-width:900px){.gt.big{grid-row:auto;aspect-ratio:4/3}.gt.wide{grid-column:auto;aspect-ratio:4/3}}
@media(max-width:520px){.gt.big{grid-column:auto}}
@media(prefers-reduced-motion:reduce){.sl,.fade span{animation:none}.s1{opacity:1}}

body.script:
//
(function(){
var f=document.getElementById('bookform');if(!f){return;}
var e=f.elements,err=document.getElementById('err');
var today=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
e.ci.min=today;e.co.min=today;
e.ci.addEventListener('change',function(){e.co.min=e.ci.value||today;if(e.co.value&&e.co.value<=e.ci.value){e.co.value='';}});
Array.prototype.forEach.call(document.querySelectorAll('[data-suite]'),function(a){a.addEventListener('click',function(){e.suite.value=a.getAttribute('data-suite');});});
f.addEventListener('submit',function(ev){
ev.preventDefault();
if(!e.ci.value||!e.co.value||e.co.value<=e.ci.value){err.textContent='Choose a check-out date that is after your check-in date.';e.co.focus();return;}
err.textContent='';
var m='Hello, I would like to request a stay at The Bliss Central, Elysium Tower.\nSuite: '+e.suite.value+'\nCheck-in: '+e.ci.value+'\nCheck-out: '+e.co.value+'\nGuests: '+e.guests.value;
window.open('https://wa.me/923365155444?text='+encodeURIComponent(m),'_blank','noopener');
});
})();
(function(){
var c=document.getElementById('cform');
if(c){c.addEventListener('submit',function(ev){ev.preventDefault();var x=c.elements;var m='Hello, my name is '+x.nm.value+'.\n'+x.msg.value+'\nMy number: '+x.ph.value;window.open('https://wa.me/923365155444?text='+encodeURIComponent(m),'_blank','noopener');});}
var mb=document.getElementById('mbtn'),tp=document.getElementById('top');
if(mb&&tp){mb.addEventListener('click',function(){var o=tp.classList.toggle('open');mb.setAttribute('aria-expanded',o?'true':'false');});
Array.prototype.forEach.call(tp.querySelectorAll('nav a'),function(a){a.addEventListener('click',function(){tp.classList.remove('open');mb.setAttribute('aria-expanded','false');});});}
})();
//
